#[test]
fn organization_and_disposal_readers_match_the_reference() {
    let memory = crate::bot::Memory::default();
    for &(input, index) in CASES {
        let line = crate::bot::Reading::new(input);
        let actual = super::chasing_a_body::respond(&line, &memory)
            .or_else(|| super::bulky::respond(&line, &memory));
        assert_eq!(actual.as_deref(), OUTCOMES[index], "{input}");
    }
}
